export function hintsFor(s){const t=truth(s);if(!t.first)return ['翻报告原件、原始收稿、打印委托和春季接力花絮。远景认人还要有交接场记。','请假说法对应3月14日下午。比对原图的独有痕迹；校刊的当周期号要与收稿日期对应。','校刊heshe口令HS032316；原始投稿收录后选折痕与蓝圈缺口。春季BV1Qh4y1p3Ct的01:24可见搬打印机；网盘码0314XSH。交接簿、请假说法与打印委托都核对后，再问陈叙。'];if(!truthy(s,'accounts','shenzhi'))return ['看沈栀授权里提到的第一次值班旧帖和广播排期。','同是周五，日期不同。要找首次值班那天的末曲，不是前后周的同位置节目。','先读授权及两份来源。首次值班9月13日，对应“夜空中最亮的星”。'];if(!truthy(s,'actions','cacheRestored'))return ['看沈栀的本地草稿缓存。','草稿编号、修订号和首尾段都要对齐，旧版尾段的结论可能已经过时。','选D0329修订02的1/2，再选同版2/2。恢复后才能确认附件出处。'];if(!truthy(s,'actions','medicalChecked')||!truthy(s,'actions','timelineChecked'))return ['分别核对医务室复查材料和后勤到场工作台，两条路都可以先走。','用药影响初检可靠性；点名要核对事件日和补录日，工作卡要有本人签收补足身份。','医疗选择R07、0329、初检不能据此排除、不能反推感染批次。到场核对m4/s3/a2/r2，解释为事后代填。'];if(!s.vault)return ['查草稿附件引用的黑板报与原加密包。','开学日期与夜宵试运行日期不同；维修记录需要同设备、同日，并包含归档。','原包口令20240912，实际解密后保留工作表。维修搜“消毒”且含归档，对20:18—21:06的专用回路停用。'];return ['把已核对的来源放进调查本，选择两张卡提出关系。','到场、漏列、运行、抽检改版、付款依据是五组不同的问题，改版和结算有方向。','点名↔流水、汇总↔复查、台账↔断电用“互相矛盾”；原单→改版用“被改写为”；合同→结算用“被用于结算”。五组后仍需查阅原件复核回函。'];}
